using AppCondominio.Contracts.Security;using AppCondominio.Modules.Reservations.Application;using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;
namespace AppCondominio.Modules.Reservations.Api;
public static class ReservationEndpoints
{
 public static IEndpointRouteBuilder MapReservationEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/reservations").RequireAuthorization();g.MapPost("/areas",async(CreateAreaRequest r,ReservationService s,CancellationToken ct)=>Results.Ok(new{Id=await s.CreateAreaAsync(r.CommunityId,r.Code,r.Name,r.Capacity,r.Fee,ct)})).RequireAuthorization(AppCondominioPermissions.Reservations.Manage);g.MapPost("/bookings",async(CreateReservationRequest r,ReservationService s,CancellationToken ct)=>Results.Ok(new{Id=await s.RequestAsync(r.AreaId,r.RequesterId,r.StartsAt,r.EndsAt,r.Guests,ct)})).RequireAuthorization(AppCondominioPermissions.Reservations.Manage);g.MapPost("/bookings/{id:guid}/confirm",async(Guid id,DecisionRequest r,ReservationService s,CancellationToken ct)=>{await s.ConfirmAsync(id,r.By,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Reservations.Manage);g.MapPost("/bookings/{id:guid}/cancel",async(Guid id,DecisionRequest r,ReservationService s,CancellationToken ct)=>{await s.CancelAsync(id,r.By,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Reservations.Manage);g.MapPost("/bookings/{id:guid}/complete",async(Guid id,ReservationService s,CancellationToken ct)=>{await s.CompleteAsync(id,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Reservations.Manage);return app;}
}
public sealed record CreateAreaRequest(Guid CommunityId,string Code,string Name,int Capacity,decimal Fee);public sealed record CreateReservationRequest(Guid AreaId,Guid RequesterId,DateTimeOffset StartsAt,DateTimeOffset EndsAt,int Guests);public sealed record DecisionRequest(string By);